# Physical constants (SI)
G = 6.67430e-11          # m³·kg⁻¹·s⁻²
c = 2.99792458e8         # m·s⁻¹
hbar = 1.054571817e-34   # J·s
k_B = 1.380649e-23       # J·K⁻¹
M_sun = 1.98847e30       # kg

def random_physical_quantity():
    """Return a randomly chosen physical quantity and its value.
    Weighted toward familiar SI units and avoids pathological extremes.
    """
    category = random.choice(['length', 'mass', 'time', 'velocity', 'acceleration', 'energy', 'power'])
    if category == 'length':
        return "meter", random.uniform(0.001, 1000)          # 1–1000 m
    elif category == 'mass':
        return "kilogram", random.uniform(0.001, 1000)        # 0.1–1000 kg
    elif category == 'time':
        return "second", random.uniform(0.001, 1000)         # 0.001–1000 s
    elif category == 'velocity':
        v_mps = random.uniform(0.001, 1000)
        if random.random() < 0.3:
            return "km/s", v_mps * 1e-3
        else:
            return "m/s", v_mps
    elif category == 'acceleration':
        a_mps2 = random.uniform(0.001, 1000)
        if random.random() < 0.2:
            return "m/s²", a_mps2
        else:
            return "g-force", a_mps2 / 9.80665
    elif category == 'energy':
        J = random.uniform(0.001, 1e6)
        if random.random() < 0.3:
            # electron‑volt (dimensionless conversion factor = 1.602e-19)
            return "eV", J * 1.602176634e19
        else:
            return "Joule", J
    elif category == 'power':
        W = random.uniform(0.001, 1e6)
        if random.random() < 0.3:
            return "hp", W / 745.7
        else:
            return "Watt", W


def check_consistency(label, value, unit):
    """Perform a lightweight dimensional consistency check.
    Converts the quantity to SI if necessary and checks against known constants.
    Returns (pass, reason).
    """
    # Convert to SI if unit is a derived prefix or common non‑SI unit
    if unit == "km/s":
        value = value * 1e3
    elif unit == "g-force":
        value = value * 9.80665
    elif unit == "eV":
        value = value * 1.602176634e-19
    elif unit == "hp":
        value = value * 745.7
    # Simple sanity checks against constants
    if label in ["G", "c", "hbar", "k_B", "M_sun"]:
        # Values are already in SI; just verify they match the constants
        return (abs(value - eval(label)) < 1e-12, f"{label} matches constant")
    else:
        # Placeholder: ensure the number is reasonable
        return (abs(value) < 1e9, "value is plausible")


def main():
    print("Random physical quantity and its SI conversion:")
    name, val = random_physical_quantity()
    unit = name
    # Perform check
    passed, reason = check_consistency(name, val, unit)
    print(f"Quantity: {name} ({unit})")
    print(f"Value: {val:.6e}")
    print(f"Check result: {'PASS' if passed else 'FAIL'} - {reason}")

if __name__ == "__main__":
    main()

