    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    rs = schwarzschild_radius(M)
    area = 4 * math.pi * rs**2
    l_p2 = planck_length()**2
    return area / (4 * l_p2)

def entropy_to_bits(S):
    # Convert Joules/Kelvin to bits using E = k_B*T*ln(2)
    # S (natural log) -> bits = S / (k_B * ln(2))
    return S / (k_B * math.log(2))

def main():
    M = M_sun  # 1 solar mass
    print(f"Schwarzschild radius of {M/M_sun:.2f} M_sun: {schwarzschild_radius(M):.3e} m")
    T = hawking_temperature(M)
    print(f"Hawking temperature: {T:.3e} K")
    S = bh_entropy(M)
    print(f"Bekenstein‑Hawking entropy: {S:.3e} J/K")
    bits = entropy_to_bits(S)
    print(f"Entropy in bits: {bits:.3e} bits")

